#include <string>
#include <vector>
#include <cctype>

class Solution {
public:
    std::vector<std::string> validateCoupons(std::vector<std::string>& coupons) {
        std::vector<std::string> valid;
        for (const auto& code : coupons) {
            if (code.size() < 8 || code.size() > 12) continue;
            bool alnum = true;
            bool has_digit = false;
            for (char ch : code) {
                if (!std::isalnum(ch)) alnum = false;
                if (std::isdigit(ch)) has_digit = true;
            }
            if (!alnum || !has_digit) continue;
            if (!std::isupper(code[0]) || !std::isupper(code[1])) continue;
            valid.push_back(code);
        }
        return valid;
    }
};

import java.util.*;

class Solution {
    public List<String> validateCoupons(String[] coupons) {
        List<String> valid = new ArrayList<>();
        for (String code : coupons) {
            if (code.length() < 8 || code.length() > 12) continue;
            boolean alnum = true;
            boolean hasDigit = false;
            for (int i = 0; i < code.length(); i++) {
                char ch = code.charAt(i);
                if (!Character.isLetterOrDigit(ch)) alnum = false;
                if (Character.isDigit(ch)) hasDigit = true;
            }
            if (!alnum || !hasDigit) continue;
            if (!Character.isUpperCase(code.charAt(0)) || !Character.isUpperCase(code.charAt(1))) continue;
            valid.add(code);
        }
        return valid;
    }
}

/**
 * @param {string[]} coupons
 * @return {string[]}
 */
var validateCoupons = function(coupons) {
    const valid = [];
    for (const code of coupons) {
        if (code.length < 8 || code.length > 12) continue;
        if (!/^[A-Za-z0-9]+$/.test(code)) continue;
        if (!/^[A-Z]{2}/.test(code)) continue;
        if (!/\d/.test(code)) continue;
        valid.push(code);
    }
    return valid;
};
